// Intended function: schedule bounded worker effort across projects by stable priority while keeping material/world commits in their owning systems.
#include "world/ConstructionPlanner.hpp"
#include <algorithm>
namespace elysium{bool ConstructionPlanner::add(ConstructionProject p){if(!p.projectId||std::find_if(projects_.begin(),projects_.end(),[&](auto&x){return x.projectId==p.projectId;})!=projects_.end())return false;projects_.push_back(std::move(p));return true;}std::vector<ConstructionWorkIntent>ConstructionPlanner::plan(const std::vector<std::uint64_t>&w,std::size_t max){auto ps=projects_;std::sort(ps.begin(),ps.end(),[](auto&a,auto&b){return a.projectId<b.projectId;});auto workers=w;std::sort(workers.begin(),workers.end());std::vector<ConstructionWorkIntent>o;std::size_t wi=0;for(auto&p:ps){if(p.stage==ConstructionStage::Complete||p.stage==ConstructionStage::Blocked)continue;if(wi>=workers.size()||o.size()>=max)break;o.push_back({p.projectId,workers[wi++],p.anchorAddress,p.stage,std::min(10.f,p.workRequired-p.workDone)});}return o;}bool ConstructionPlanner::applyWork(std::uint64_t id,float work){auto i=std::find_if(projects_.begin(),projects_.end(),[&](auto&p){return p.projectId==id;});if(i==projects_.end()||i->stage==ConstructionStage::Blocked||i->stage==ConstructionStage::Complete)return false;i->workDone+=std::max(0.f,work);if(i->workDone>=i->workRequired){i->workDone=0;i->stage=i->stage==ConstructionStage::Finish?ConstructionStage::Complete:ConstructionStage(std::uint8_t(i->stage)+1);}return true;}std::vector<ConstructionProject>ConstructionPlanner::projects()const{auto o=projects_;std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.projectId<b.projectId;});return o;}}
